      "compilation_sha256": "669c276109b9b6e07b7e6674e5f0ee4fa45d79b7987656c28c3919a2f13eaea6",
      "approved_on": "2026-08-18"
    },
    {
      "control_id": "ustb-yield-one-day-present",
      "compilation_sha256": "669c276109b9b6e07b7e6674e5f0ee4fa45d79b7987656c28c3919a2f13eaea6",
      "approved_on": "2026-08-18"
    }
  ],
  "declined": [
    {
      "control_id": "ustb-holdings-recently-published",
      "compilation_sha256": "fad12109e3ec919ec87d923ee628392f3b64c91269711b5626a5b8239843afc3",
      "declined_on": "2026-08-18",
      "reason": "Redundant with ustb-holdings-as-of-date-present: both read the same as_of_date, and a 40-calendar-day window on a monthly holdings file adds no claim the presence control does not already make."
    },
    {
      "control_id": "ustb-outstanding-shares-present",
      "compilation_sha256": "db4eebc0e7a795eec7d835dfc4ccd939b87dd3a86d4c4e30a8b1c028bebb4bba",
      "declined_on": "2026-08-18",
      "reason": "Compiler confidence is 0.80 against a gate of < 0.80, so it clears by zero margin. That is not a deterministic invalidity and the candidate is well formed, but zero margin is not the evidence quality a first approved set should rest on when ustb-nav-per-share-present already covers the NAV value claim."
    },
    {
      "control_id": "ustb-yield-as-of-date-present",
      "compilation_sha256": "669c276109b9b6e07b7e6674e5f0ee4fa45d79b7987656c28c3919a2f13eaea6",
      "declined_on": "2026-08-18",
      "reason": "Redundant with ustb-yield-as-of-date-fresh, which reads the same field and also checks it against the source's declared two-business-day policy."
    },
    {
      "control_id": "ustb-yield-seven-day-present",
      "compilation_sha256": "669c276109b9b6e07b7e6674e5f0ee4fa45d79b7987656c28c3919a2f13eaea6",
      "declined_on": "2026-08-18",
      "reason": "Valid, but a third presence check on the same yield document is additional scalar coverage rather than breadth. ustb-yield-one-day-present is the representative field; approving all three would present duplication as product scope."
    },
    {
      "control_id": "ustb-yield-thirty-day-present",
      "compilation_sha256": "669c276109b9b6e07b7e6674e5f0ee4fa45d79b7987656c28c3919a2f13eaea6",
      "declined_on": "2026-08-18",
      "reason": "Valid, but a third presence check on the same yield document is additional scalar coverage rather than breadth. ustb-yield-one-day-present is the representative field; approving all three would present duplication as product scope."
    }
  ]
}
